// P12 로컬 골격: WORKFLOW-DESIGN 6.1의 LookupRequest/TicketRequest를 검사한다.
// state 하위 기능과 Jira가 합의·연결되기 전에는 외부 조회/생성/변경을 절대 실행하지 않는다.
const input = $json.body ?? $json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const isText = (v) => typeof v === 'string' && v.trim().length > 0;
const isStateRef = (v) => isObj(v) && isText(v.scope) && isText(v.request_id) && isText(v.owner_id) && isText(v.input_hash) && isText(v.execution_id) && Number.isInteger(v.state_revision) && v.state_revision >= 0;
const effect = () => ({ status: 'none' });
const effects = () => ({ created_or_reused: effect(), context_saved: effect(), closed: effect(), assigned: effect(), alert: effect() });

if (!isObj(input) || !isText(input.request_id) || !['lookup', 'process'].includes(input.kind)) {
  return [{ json: { body: { request_id: isObj(input) && isText(input.request_id) ? input.request_id : null, status: 'error', record: null, masked: 0, error_code: 'invalid_tool_request' }, http_status: 400 } }];
}

if (input.kind === 'lookup') {
  const valid = typeof input.enabled === 'boolean' && isText(input.actor_id) && (input.target_ticket_id === null || isText(input.target_ticket_id));
  if (!valid) {
    return [{ json: { body: { request_id: input.request_id, status: 'error', record: null, masked: 0, error_code: 'invalid_tool_request' }, http_status: 400 } }];
  }
  if (!input.enabled) {
    return [{ json: { body: { request_id: input.request_id, status: 'skipped', record: null, masked: 0, error_code: null }, http_status: 200 } }];
  }
  return [{ json: { body: { request_id: input.request_id, status: 'error', record: null, masked: 0, error_code: 'handoff_backend_unconfigured' }, http_status: 200 } }];
}

const validProcess = isStateRef(input.state_ref) && isText(input.case_id) && isText(input.actor_id) && isText(input.first_request_id) && Number.isInteger(input.attempt) && input.attempt >= 1 && (input.ticket_id === null || isText(input.ticket_id)) && isText(input.title) && isText(input.category) && ['close', 'wait', 'handoff'].includes(input.action) && ['normal', 'high'].includes(input.priority) && isObj(input.context) && typeof input.answer === 'string' && Array.isArray(input.sources) && isText(input.transition_key);
const errorCode = validProcess ? 'state_backend_unconfigured' : 'invalid_tool_request';
return [{ json: { body: {
  request_id: input.request_id,
  ticket_id: input.ticket_id ?? null,
  case_version: null,
  state_saved: false,
  state_ref: null,
  recovery: { version: 1, mode: 'manual_required', action: validProcess ? 'create' : 'inspect_only', args: null, reference: null, reason: validProcess ? 'state/Jira 미연결로 외부 작업 차단' : '티켓 요청 계약 오류' },
  effects: effects(),
  error_code: errorCode
}, http_status: validProcess ? 200 : 400 } }];
